"""Community and homeowner resources from the owner's October 2026 plan."""
from html import escape
TRANSLATIONS={}
def t(en,fr):
    TRANSLATIONS[en]=fr
    return en

def p(en,fr): return '<p>'+t(en,fr)+'</p>'
def h(en,fr): return '<h2>'+t(en,fr)+'</h2>'
def button(url,en,fr,style=''): return f'<a class="button {style}" href="{url}">{t(en,fr)}</a>'
def actions(*items): return '<div class="plan-actions">'+''.join(button(*i) for i in items)+'</div>'
def cards(items):
    return '<div class="plan-card-grid">'+''.join(f'<a class="plan-card" href="{url}"><span class="eyebrow">{i+1:02}</span><h3>{t(en,fr)}</h3><p>{t(desc,descfr)}</p></a>' for i,(url,en,fr,desc,descfr) in enumerate(items))+'</div>'

def home_additions():
    return '<section class="wrap section community-now"><div class="section-heading"><div><p class="eyebrow">'+t('ON THE LOCAL CALENDAR','AU CALENDRIER LOCAL')+'</p>'+h('Make a little time for Nobleton.','Prenez un moment pour Nobleton.')+'</div><a class="text-link" href="/events/">'+t('All events & official calendars','Événements et calendriers officiels')+'</a></div><div class="homepage-events">'+event_cards().replace('<h2>','<h3>').replace('</h2>','</h3>')+'</div><p id="no-upcoming-events" hidden>'+t('Visit our events page for official calendars and upcoming activities.','Consultez la page des événements pour les calendriers officiels et activités à venir.')+'</p><p class="fine">'+t('Local Ontario times. Details checked November 9, 2026; confirm with the organizer before attending.','Heures locales de l’Ontario. Détails vérifiés le 9 novembre 2026; confirmez auprès de l’organisateur.')+'</p></section>'


def homeowner_links():
    return '<section class="wrap section">'+h('Your next move, a little clearer.','Votre prochain déménagement, en toute clarté.')+cards([
      ('/homes-for-sale/','Explore homes for sale','Explorez les maisons à vendre','Start a personal search while our listing feed is being arranged.','Commencez une recherche personnalisée pendant la mise en place du flux d’annonces.'),
      ('/guide/buying-a-home/','Buying your first or next home','Acheter votre première ou prochaine maison','A practical path from your budget to closing day.','Un parcours pratique, du budget à la prise de possession.'),
      ('/mortgage-calculator/','Understand the numbers','Comprenez les chiffres','Estimate Canadian mortgage payments, down payments and insurance.','Estimez les versements hypothécaires, la mise de fonds et l’assurance au Canada.')])+'</section>'

def realtor_bio():
    return '<section class="wrap section profile-story"><div><p class="eyebrow">'+t('ABOUT EKATERINA','À PROPOS D’EKATERINA')+'</p>'+h('Experience with a personal perspective.','L’expérience et une approche personnelle.')+'</div><div>'+p('With over 13 years of real estate experience and a background in finance, Ekaterina brings market knowledge, strong negotiation skills and a personalized approach to every transaction.','Forte de plus de 13 ans d’expérience en immobilier et d’une formation en finance, Ekaterina allie connaissance du marché, talents de négociatrice et approche personnalisée à chaque transaction.')+p('Having lived in York Region for over 20 years, she understands the local housing market and the importance of helping clients make informed decisions. Whether buying, selling or investing, she provides practical advice, clear communication and guidance throughout the process.','Résidente de la région de York depuis plus de 20 ans, elle connaît le marché local et l’importance de décisions éclairées. Achat, vente ou investissement : elle offre des conseils pratiques, une communication claire et un accompagnement à chaque étape.')+p('Every property is different, every deal has a story, and every client deserves individual attention.','Chaque propriété est différente, chaque transaction a son histoire et chaque client mérite une attention particulière.')+'<a class="text-link" href="https://www.instagram.com/family.realtor/">Instagram · @family.realtor</a>'+actions(('/ask-realtor/','Ask Ekaterina','Poser une question à Ekaterina'),('/home-evaluation/','What’s my home worth?','Quelle est la valeur de ma maison?'),('/homes-for-sale/','Explore homes','Explorer les propriétés'))+'</div></section>'

def mortgage_links():
    return '<section class="wrap section">'+h('Make your next move with confidence.','Préparez votre prochain projet avec confiance.')+p('Start with a question, a conversation or an estimate. Your circumstances and goals shape the right financing discussion.','Commencez par une question, une conversation ou une estimation. Votre situation et vos objectifs orientent la discussion sur le financement.')+actions(('/mortgage-consultation/?topic=question','Ask a mortgage question','Poser une question hypothécaire'),('/mortgage-consultation/','Request a consultation','Demander une consultation'),('/mortgage-calculator/','Calculate my payment','Calculer mon versement'))+cards([
      ('/guide/down-payments/','Down payments & affordability','Mise de fonds et capacité d’achat','Understand minimum down payments, insurance and cash for closing.','Comprenez la mise de fonds minimale, l’assurance et les fonds nécessaires à la clôture.'),
      ('/guide/mortgage-renewal/','Renewal, refinance & investment','Renouvellement, refinancement et investissement','Prepare the questions that help you compare financing options.','Préparez les questions utiles pour comparer vos options de financement.'),
      ('/guide/selling-and-buying/','Selling and buying again','Vendre pour acheter','Connect your current property’s value with your next-home budget.','Reliez la valeur de votre propriété actuelle au budget de votre prochain achat.')])+'</section>'

def professional_form(kind):
    realtor=kind in ('realtor','valuation')
    who='Ekaterina Ottchenach' if realtor else 'Anatoly Shibkov'
    email='realtor@nobleton.ca' if realtor else 'mortgage@nobleton.ca'
    field=lambda ident,label,fr,typ='text',extra='': f'<label for="{ident}">{t(label,fr)}</label><input id="{ident}" name="{ident}" type="{typ}" {extra}>'
    fields=field('name','Full name','Nom complet',extra='autocomplete="name" maxlength="100" required')+field('email','Email address','Adresse courriel','email','autocomplete="email" maxlength="180" required')+field('phone','Phone (optional)','Téléphone (facultatif)','tel','autocomplete="tel" maxlength="40"')
    if kind=='valuation': fields+=field('address','Property address','Adresse de la propriété',extra='autocomplete="street-address" maxlength="250" required')
    if kind=='mortgage':
        fields+='<label for="topic">'+t('What would you like to discuss?','De quoi souhaitez-vous discuter?')+'</label><select id="topic" name="topic">'+''.join(f'<option value="{v}">{t(en,fr)}</option>' for v,en,fr in [('consultation','Mortgage consultation','Consultation hypothécaire'),('question','A mortgage question','Une question hypothécaire'),('purchase','Purchase & pre-approval','Achat et préapprobation'),('renewal','Renewal','Renouvellement'),('refinance','Refinance','Refinancement'),('investment','Investment financing','Financement d’investissement')])+'</select>'
    fields+='<label for="message">'+t('Comments (optional)' if kind=='valuation' else 'Your question or plans','Commentaires (facultatifs)' if kind=='valuation' else 'Votre question ou votre projet')+'</label><textarea id="message" name="message" rows="5" maxlength="2500" '+('' if kind=='valuation' else 'required')+'></textarea>'
    consent=t('I agree that Nobleton.ca may send this inquiry to '+who+' so they can respond to my request.','J’accepte que Nobleton.ca transmette cette demande à '+who+' afin d’y répondre.')
    both=t('Optional: also share my inquiry with the other featured professional so both Ekaterina and Anatoly may contact me about this request.','Facultatif : transmettre aussi ma demande à l’autre professionnel présenté afin qu’Ekaterina et Anatoly puissent tous deux me contacter à ce sujet.')
    return f'''<form class="email-form professional-form" action="https://nobleton.ca/api/inquiry.php" method="post" data-kind="{kind}"><input type="hidden" name="kind" value="{kind}"><input type="hidden" name="source_page" value="/{ {'realtor':'ask-realtor','valuation':'home-evaluation','mortgage':'mortgage-consultation'}[kind] }/"><input type="hidden" name="preferred_language" value="en-CA"><div class="form-trap" aria-hidden="true"><label for="company-url">Website</label><input id="company-url" name="company_url" tabindex="-1" autocomplete="off"></div>{fields}<p class="fine">{t('Please leave out financial account numbers, identification documents and other sensitive information.','Veuillez omettre les numéros de comptes financiers, pièces d’identité et autres renseignements sensibles.')}</p><label class="check"><input type="checkbox" name="consent" value="yes" required><span>{consent}</span></label><label class="check"><input type="checkbox" name="both" value="yes"><span>{both}</span></label><p class="fine">{t('Sent through Nobleton.ca’s hosting service to the professional you select.','Transmis par le service d’hébergement de Nobleton.ca au professionnel choisi.')} <a href="/privacy/">{t('Privacy information','Renseignements sur la confidentialité')}</a></p><button class="button" type="submit">{t('Send my request','Envoyer ma demande')}</button><p class="professional-status" role="status" tabindex="-1"></p><p class="fine">{t('Prefer email?','Vous préférez le courriel?')} <a href="mailto:{email}">{email}</a></p></form>'''

def privacy_addition():
    return h('Professional inquiries','Demandes aux professionnels')+p('Real estate and home-evaluation forms are addressed to Ekaterina Ottchenach at realtor@nobleton.ca. Mortgage forms are addressed to Anatoly Shibkov at mortgage@nobleton.ca. The form sends your name, email, optional phone, message, language, source page and property address if you request an evaluation.','Les formulaires immobiliers et d’évaluation sont adressés à Ekaterina Ottchenach à realtor@nobleton.ca. Les formulaires hypothécaires sont adressés à Anatoly Shibkov à mortgage@nobleton.ca. Ils transmettent votre nom, courriel, téléphone facultatif, message, langue, page d’origine et adresse de la propriété pour une évaluation.')+p('Only the selected professional receives the inquiry unless you separately select the optional permission for both professionals. This permission relates to your request; it is not a newsletter subscription. Inquiry delivery uses our WHC hosting and email services. We do not save inquiry contents in a website database or in browser storage. Copies may remain in the receiving mailboxes and mail-service logs.','Seul le professionnel choisi reçoit la demande, sauf si vous autorisez séparément la transmission aux deux professionnels. Cette autorisation concerne votre demande; elle ne constitue pas un abonnement à une infolettre. La transmission utilise les services d’hébergement et de courriel WHC. Le contenu n’est enregistré ni dans une base de données du site ni dans le navigateur. Des copies peuvent demeurer dans les boîtes de réception et journaux du service de messagerie.')+p('To limit abuse, the server keeps temporary counters based on a hash of the requesting IP address. Hosting access logs may separately contain technical request details. Contact info@nobleton.ca or the receiving professional to ask about access, correction or deletion of your information.','Pour limiter les abus, le serveur conserve des compteurs temporaires fondés sur une empreinte de l’adresse IP. Les journaux d’hébergement peuvent contenir des détails techniques distincts. Contactez info@nobleton.ca ou le professionnel destinataire pour demander l’accès, la correction ou la suppression de vos renseignements.')+h('Calculator and optional analytics','Calculatrice et statistiques facultatives')+p('Mortgage estimates are calculated in your browser. We do not send or store the values you enter. Google Analytics 4 loads only after you choose to allow optional analytics. It uses cookies to measure visits and interactions. You can decline or change your choice using Analytics preferences.','Les estimations hypothécaires sont calculées dans votre navigateur. Les valeurs saisies ne sont ni transmises ni conservées. Google Analytics 4 se charge seulement avec votre accord pour les statistiques facultatives. Il utilise des témoins pour mesurer les visites et interactions. Vous pouvez refuser ou modifier votre choix dans Préférences de statistiques.')+p('Optional analytics record page paths and interaction types, such as a contact click or inquiry submission. Form contents, email addresses, property addresses and calculator amounts are excluded. Search queries are removed from page URLs sent to analytics. External services have their own privacy practices.','Les statistiques facultatives enregistrent les chemins des pages et les types d’interaction, comme un clic de contact ou un envoi de demande. Le contenu des formulaires, courriels, adresses et montants de la calculatrice sont exclus. Les paramètres de recherche sont retirés des URL transmises. Les services externes ont leurs propres pratiques de confidentialité.')+'<button class="text-link analytics-preferences" type="button" hidden>'+t('Analytics preferences','Préférences de statistiques')+'</button>'


def register_pages(page,intro,photo):
    def make(slug,title,frtitle,desc,frdesc,content,kicker='YOUR NOBLETON',frkicker='VOTRE NOBLETON'):
        page(slug,t(title,frtitle),t(desc,frdesc),intro(t(kicker,frkicker),t(title,frtitle),t(desc,frdesc))+content)
    make('homes-for-sale','Explore homes for sale in Nobleton','Explorez les maisons à vendre à Nobleton','Your next chapter starts with the right neighbourhood, the right questions and a search built around you.','Votre prochain chapitre commence par le bon quartier, les bonnes questions et une recherche adaptée à vos besoins.',
        '<section class="wrap section split-feature"><div>'+photo('nobleton-hambly-house','Red-brick Hambly House with its central tower in Nobleton','')+'</div><div><p class="eyebrow">'+t('A PERSONAL START','UN DÉPART PERSONNALISÉ')+'</p>'+h('Tell us what home looks like.','Décrivez-nous votre maison idéale.')+p('Buying your first home, moving up, downsizing or exploring an investment? Ekaterina can help you discuss properties in Nobleton, King City, Schomberg, Pottageville and surrounding communities.','Premier achat, maison plus grande, réduction d’espace ou investissement? Ekaterina peut vous aider à explorer les propriétés à Nobleton, King City, Schomberg, Pottageville et dans les environs.')+actions(('/ask-realtor/','Start my home search','Commencer ma recherche'),('/home-evaluation/','What’s my home worth?','Quelle est la valeur de ma maison?'))+'<aside class="note">'+h('Online listings are coming.','Les annonces en ligne arrivent.')+p('Our live property search is not available yet. It will launch after the required website-specific data agreement and feed permissions are in place. Contact Ekaterina for help with a current search.','La recherche de propriétés en direct n’est pas encore disponible. Elle sera lancée après la mise en place de l’entente de données et des autorisations propres au site. Contactez Ekaterina pour une recherche actuelle.')+'</aside></div></section>'+homeowner_links().replace('<section class="wrap section">','<section class="wrap section related-home-resources">',1))
    for kind,slug,title,frtitle,desc,frdesc in [
      ('valuation','home-evaluation','Curious what your Nobleton home is worth?','Quelle est la valeur de votre maison à Nobleton?','Request a personalized market evaluation based on comparable sales, property features and local market conditions.','Demandez une évaluation personnalisée fondée sur les ventes comparables, les caractéristiques de votre propriété et le marché local.'),
      ('realtor','ask-realtor','Ask Ekaterina about your next move.','Parlez de votre projet à Ekaterina.','Questions about buying, selling, property values or neighbourhoods? Start a conversation.','Des questions sur l’achat, la vente, la valeur d’une propriété ou les quartiers? Commençons la conversation.'),
      ('mortgage','mortgage-consultation','Make your next move with confidence.','Préparez votre prochain projet avec confiance.','Ask a mortgage question or request a consultation about purchasing, renewal, refinancing or investment financing.','Posez une question ou demandez une consultation sur l’achat, le renouvellement, le refinancement ou l’investissement.')]:
        isre=kind!='mortgage'; who='Ekaterina Ottchenach' if isre else 'Anatoly Shibkov'
        phone='(647) 838-5569' if isre else '(437) 255-5037'; tel='+16478385569' if isre else '+14372555037'
        broker='HomeLife Frontier Realty Inc., Brokerage' if isre else 'Mortgage Architects Professionals Inc.'
        img='ekaterina-ottchenach.webp' if isre else 'anatoly-shibkov.jpg'
        aside=f'<aside class="form-professional"><img src="/assets/images/{img}" width="280" height="340" alt="{who}" loading="lazy"><h2>{who}</h2><p>'+t('Real Estate Sales Representative','Représentante des ventes immobilières')+'</p>' if isre else f'<aside class="form-professional"><img src="/assets/images/{img}" width="280" height="340" alt="{who}" loading="lazy"><h2>{who}</h2><p>'+t('Mortgage Agent','Agent hypothécaire')+'</p>'
        aside+=f'<p>{broker}</p>'+(p('7620 Yonge St #400, Thornhill, ON L4J 1V9','7620 Yonge St #400, Thornhill, ON L4J 1V9') if isre else p('Brokerage Licence #12168','Permis de courtage no 12168'))+f'<a class="text-link" href="tel:{tel}">{phone}</a>'
        if kind=='valuation': aside+=p('This is a request for a market opinion, not an automated valuation or a formal appraisal. Ekaterina will review your property details with you.','Il s’agit d’une demande d’avis sur la valeur marchande, et non d’une estimation automatisée ou d’une évaluation agréée. Ekaterina examinera avec vous les détails de votre propriété.')
        aside+='</aside>'
        make(slug,title,frtitle,desc,frdesc,'<section class="wrap section form-layout">'+aside+professional_form(kind)+'</section>')
    make('contact','Have a question? We’re here to help.','Une question? Nous sommes là pour vous.','Choose the professional best suited to your question. You decide who receives your inquiry.','Choisissez le professionnel qui peut répondre à votre question. Vous décidez qui reçoit votre demande.', '<section class="wrap section">'+cards([
       ('/ask-realtor/','Ask Ekaterina','Demandez à Ekaterina','Buying, selling, home values, neighbourhoods and investment properties.','Achat, vente, valeur des maisons, quartiers et propriétés d’investissement.'),
       ('/mortgage-consultation/','Ask Anatoly','Demandez à Anatoly','Pre-approvals, down payments, renewals, refinancing and financing options.','Préapprobations, mises de fonds, renouvellements, refinancements et financement.'),
       ('/find-a-service/','Ask the community team','Contactez l’équipe du site','Local services, directory suggestions and community questions.','Services locaux, suggestions pour le répertoire et questions communautaires.')])+'</section>')
    guides=[
      ('buying-a-home','Buying a home in Nobleton? Start here.','Acheter à Nobleton? Commencez ici.','A practical path from planning your budget to preparing for closing.','Un parcours pratique, de la planification du budget à la clôture.',[
       ('1. Understand your budget','1. Comprenez votre budget','Review your income, ongoing expenses, savings and a comfortable payment range. Discuss pre-approval with a mortgage professional before shopping. A pre-approval is conditional; the lender still needs to review the property and your circumstances before a final commitment.','Examinez vos revenus, dépenses, économies et capacité de remboursement. Discutez d’une préapprobation avant de chercher. Elle demeure conditionnelle : le prêteur doit encore examiner la propriété et votre situation avant de s’engager.'),
       ('2. Explore homes and neighbourhoods','2. Explorez les propriétés et quartiers','Define your priorities, then compare Nobleton and nearby communities. Check address-specific school eligibility, transportation, property services and amenities. Ask Ekaterina about current homes while our online feed is being arranged.','Définissez vos priorités, puis comparez Nobleton et les communautés voisines. Vérifiez l’admissibilité scolaire selon l’adresse, les déplacements, les services et commodités. Demandez à Ekaterina les propriétés disponibles pendant la mise en place du flux en ligne.'),
       ('3. Plan showings and an offer','3. Préparez les visites et une offre','Discuss comparable sales, property condition and the terms that matter to you. Your representative can help you assess an offer strategy and appropriate conditions. Arrange inspections and professional advice suited to the property.','Discutez des ventes comparables, de l’état de la propriété et des conditions importantes pour vous. Votre représentante peut vous aider à évaluer une stratégie d’offre et les conditions appropriées. Prévoyez les inspections et conseils professionnels adaptés.'),
       ('4. Prepare for closing','4. Préparez la clôture','Confirm financing, legal arrangements, insurance, deposit deadlines and remaining cash needed. Budget for closing expenses and adjustments as well as the down payment. Keep written confirmations and coordinate the handover with your professionals.','Confirmez le financement, les démarches juridiques, l’assurance, les échéances du dépôt et les fonds restants. Prévoyez les frais de clôture et ajustements en plus de la mise de fonds. Conservez les confirmations écrites et coordonnez la prise de possession.')]),
      ('selling-and-buying','Thinking about your next move?','Vous pensez à votre prochain déménagement?','Connect the value of your current home with the cost and timing of your next one.','Reliez la valeur de votre maison actuelle au coût et au calendrier de votre prochain achat.',[
       ('Start with two numbers','Commencez par deux chiffres','What might your current home sell for, and what can you comfortably afford next? Request a market evaluation and review your financing before making commitments. Estimated sale proceeds should account for your mortgage balance, selling costs and any applicable mortgage charges.','À quel prix votre maison pourrait-elle se vendre, et quel achat pouvez-vous raisonnablement financer? Demandez une évaluation et examinez le financement avant de vous engager. Les produits estimés de la vente doivent tenir compte du solde hypothécaire, des frais de vente et des frais hypothécaires applicables.'),
       ('Buying before selling','Acheter avant de vendre','You may secure your next home first, but this can create overlapping carrying costs and uncertainty about sale proceeds. Ask your mortgage professional whether bridge financing is available and what conditions apply; it is not automatic.','Vous pouvez trouver votre prochaine maison d’abord, mais cela peut créer des coûts simultanés et une incertitude sur le produit de la vente. Demandez si un financement relais est offert et sous quelles conditions; il n’est pas automatique.'),
       ('Selling before buying','Vendre avant d’acheter','Knowing your sale terms can make planning easier. Consider temporary accommodation, moving and storage costs if closing dates do not align. Discuss timing, conditions and contingencies with your representative and lawyer.','Connaître les conditions de vente peut faciliter la planification. Prévoyez l’hébergement temporaire, le déménagement et l’entreposage si les dates ne concordent pas. Discutez du calendrier, des conditions et des imprévus avec votre représentante et votre avocat.'),
       ('Check your current mortgage','Vérifiez votre prêt actuel','Ask about portability, discharge costs and any prepayment penalty before you decide on a sale date. Your lender or mortgage professional can explain the options in your actual contract.','Renseignez-vous sur la transférabilité, les frais de radiation et toute pénalité de remboursement anticipé avant de fixer une date. Votre prêteur ou professionnel hypothécaire peut expliquer les options de votre contrat.')]),
      ('down-payments','How much down payment do you need?','Quelle mise de fonds faut-il prévoir?','Understand the minimum, the insurance and the cash you still need at closing.','Comprenez le minimum, l’assurance et les fonds nécessaires à la clôture.',[
       ('Minimum down payment','Mise de fonds minimale','For an eligible insured purchase below $1.5 million, the minimum is 5% of the first $500,000 plus 10% of the amount above $500,000. A purchase of $1.5 million or more requires at least 20% down. Lenders may require more based on the property and your circumstances.','Pour un achat admissible à l’assurance de moins de 1,5 million de dollars, le minimum est de 5 % des premiers 500 000 $ et de 10 % de l’excédent. Un achat de 1,5 million de dollars ou plus exige au moins 20 %. Les prêteurs peuvent exiger davantage selon la propriété et votre situation.'),
       ('Mortgage default insurance','Assurance prêt hypothécaire','With less than 20% down, an eligible purchase generally needs mortgage default insurance. It protects the lender, not the borrower. The premium can usually be added to the loan; Ontario’s 8% tax on the premium must be paid separately. Our calculator estimates these amounts using CMHC’s published standard premiums.','Avec moins de 20 % de mise de fonds, un achat admissible nécessite généralement une assurance prêt hypothécaire. Elle protège le prêteur, pas l’emprunteur. La prime peut habituellement être ajoutée au prêt; la taxe ontarienne de 8 % sur la prime doit être payée séparément. Notre calculatrice utilise les primes standards publiées par la SCHL.'),
       ('Keep room for closing and everyday life','Prévoyez la clôture et les dépenses courantes','Your down payment is only part of the cash required. Ask your lawyer and mortgage professional to estimate land transfer tax, legal costs, adjustments and any other applicable expenses. Leave room for maintenance, utilities and an emergency reserve.','La mise de fonds n’est qu’une partie des fonds requis. Demandez une estimation des droits de mutation, frais juridiques, ajustements et autres frais applicables. Prévoyez l’entretien, les services publics et une réserve d’urgence.')]),
      ('mortgage-renewal','Renewal, refinance or investment?','Renouvellement, refinancement ou investissement?','Prepare for a useful financing conversation before your next decision.','Préparez une discussion utile sur le financement avant votre prochaine décision.',[
       ('Mortgage renewal','Renouvellement hypothécaire','Start comparing before your current term ends. Review the proposed rate, term, payment flexibility, prepayment privileges and penalties. Switching lenders may involve a new application and costs, so compare the full terms rather than the rate alone.','Commencez à comparer avant la fin du terme. Examinez le taux proposé, le terme, la souplesse des versements, les privilèges et pénalités de remboursement anticipé. Changer de prêteur peut nécessiter une nouvelle demande et des frais : comparez l’ensemble des conditions.'),
       ('Refinancing','Refinancement','Refinancing changes your borrowing arrangement and may involve new qualification, appraisal, legal costs and a prepayment penalty. Consider the total interest and length of repayment, especially when consolidating other debts into a mortgage.','Le refinancement modifie l’emprunt et peut nécessiter une nouvelle qualification, une évaluation, des frais juridiques et une pénalité. Considérez le coût total des intérêts et la durée, surtout si vous regroupez d’autres dettes dans le prêt hypothécaire.'),
       ('Investment property financing','Financement d’une propriété d’investissement','Financing depends on occupancy, property type, rental income and lender requirements. Discuss your intended use and the records needed before making an offer. Our owner-occupied mortgage calculator is not an investment-property qualification tool.','Le financement dépend de l’occupation, du type de propriété, des revenus locatifs et des exigences du prêteur. Discutez de l’usage prévu et des documents requis avant une offre. Notre calculatrice pour propriétaire occupant n’est pas un outil de qualification pour investissement.'),
       ('Bring the right questions','Préparez les bonnes questions','Ask what costs apply, which conditions remain, how payments may change and what happens if you sell or repay early. Share financial documents directly through your professional’s secure process, not the website inquiry form.','Demandez quels frais s’appliquent, quelles conditions restent à remplir, comment les versements peuvent changer et les conséquences d’une vente ou d’un remboursement anticipé. Transmettez les documents financiers par le processus sécurisé de votre professionnel, pas par le formulaire du site.')])]
    for slug,title,frtitle,desc,frdesc,sections in guides:
        content='<article class="wrap reading section">'+''.join(h(a,b)+p(c,d) for a,b,c,d in sections)
        content+='<aside class="note">'+p('General information, not personalized financial or legal advice. Eligibility and actual terms depend on the lender, insurer and property. Reviewed November 9, 2026.','Renseignements généraux, sans conseil financier ou juridique personnalisé. L’admissibilité et les conditions dépendent du prêteur, de l’assureur et de la propriété. Révisé le 9 novembre 2026.')+'<a href="https://www.canada.ca/en/financial-consumer-agency/services/mortgages.html">'+t('Mortgage information from the Financial Consumer Agency of Canada','Renseignements hypothécaires de l’Agence de la consommation en matière financière du Canada')+'</a>'
        if slug=='down-payments': content+='<p><a href="https://www.cmhc-schl.gc.ca/consumers/home-buying/mortgage-loan-insurance-for-consumers/what-are-the-general-requirements-to-qualify-for-homeowner-mortgage-loan-insurance">'+t('CMHC eligibility and down-payment requirements','Admissibilité et mise de fonds : SCHL')+'</a></p>'
        content+='</aside>'+actions(('/home-evaluation/','Request a home evaluation','Demander une évaluation'),('/mortgage-consultation/','Discuss mortgage options','Discuter du financement'),('/homes-for-sale/','Explore homes','Explorer les propriétés'))+'</article>'
        make('guide/'+slug,title,frtitle,desc,frdesc,content)
    register_community(make,photo)
    register_calculator(make)
    make('thank-you','Your request has been submitted.','Votre demande a été envoyée.','Thank you for starting a conversation. The selected professional can follow up using the contact details you provided.','Merci d’avoir commencé la conversation. Le professionnel choisi pourra vous répondre aux coordonnées fournies.','<section class="wrap section">'+actions(('/','Back to Nobleton','Retour à Nobleton'),('/contact/','Contact options','Options de contact'))+'</section>')


def current_news():
    return '<section class="wrap section">'+h('Community updates · November 2026','Nouvelles locales · Novembre 2026')+cards([
      ('https://www.king.ca/your-local-government/news-and-notices/news-releases/notice-public-planning-meeting-concerning-6','Planning notice: Old King Road','Avis d’aménagement : Old King Road','A public planning meeting for 25 & 31 Old King Road, Nobleton is scheduled for November 30, 2026 at 6 p.m. Read the Township notice for the proposal and participation details.','Une réunion publique sur l’aménagement au 25 et 31 Old King Road, Nobleton est prévue le 30 novembre 2026 à 18 h. Consultez l’avis du canton pour le projet et les modalités de participation.'),
      ('https://www.king.ca/your-local-government/news-and-notices/news-releases/dine-local-and-savour-season-during-taste-king','Taste of King · November 6–22','Taste of King · Du 6 au 22 novembre','The Township’s fall dining event includes participating restaurants across Nobleton, King City and Schomberg. Check the official announcement for menus and reservations.','L’événement gastronomique d’automne du canton réunit des restaurants de Nobleton, King City et Schomberg. Consultez l’annonce officielle pour les menus et réservations.')])+'<p class="fine">'+t('Selected official notices, checked November 9, 2026. Follow the linked sources for changes.','Sélection d’avis officiels, vérifiés le 9 novembre 2026. Consultez les sources pour les mises à jour.')+'</p></section>'

def guide_resources():
    return '<section class="wrap section">'+h('Home and financing guides','Guides immobiliers et hypothécaires')+cards([
      ('/guide/buying-a-home/','Buying a home','Acheter une maison','From your budget to your closing checklist.','Du budget à la liste de vérification pour la clôture.'),
      ('/guide/selling-and-buying/','Selling and buying','Vendre et acheter','Plan your sale, next purchase and financing together.','Planifiez ensemble la vente, le prochain achat et le financement.'),
      ('/guide/down-payments/','Down payments','Mises de fonds','Understand the minimum, insurance and closing cash.','Comprenez le minimum, l’assurance et les fonds nécessaires à la clôture.'),
      ('/guide/mortgage-renewal/','Renewal and refinancing','Renouvellement et refinancement','Prepare your questions before choosing new terms.','Préparez vos questions avant de choisir de nouvelles conditions.')])+'</section>'

def event_cards():
    events=[
      ('2026-11-14','NOV','14','Fall Feeders for Feathered Friends','Mangeoires d’automne pour nos amis à plumes','November 14, 2026 · 10–11:30 a.m.','14 novembre 2026 · 10 h à 11 h 30','Cold Creek Visitor Centre · 14125 11th Concession, Nobleton','Centre d’accueil de Cold Creek · 14125 11th Concession, Nobleton','$5 + HST · Registration required','5 $ + TVH · Inscription requise','https://www.king.ca/EnvironmentalEvents'),
      ('2026-11-28','NOV','28','Community electronic recycling','Collecte communautaire de déchets électroniques','November 28, 2026 · 9 a.m.–noon','28 novembre 2026 · 9 h à midi','Nobleton Arena parking lot · 15 Old King Road','Stationnement de l’aréna de Nobleton · 15 Old King Road','Free · Check accepted items before you go','Gratuit · Vérifiez les articles acceptés avant de partir','https://www.king.ca/electronicrecycling'),
      ('2026-12-12','DEC','12','Winter Woodland Creations','Créations hivernales de la forêt','December 12, 2026 · 10 a.m.–noon','12 décembre 2026 · 10 h à midi','Cold Creek Education Centre · 14125 11th Concession, Nobleton','Centre éducatif de Cold Creek · 14125 11th Concession, Nobleton','$15 + HST · Registration required','15 $ + TVH · Inscription requise','https://www.king.ca/EnvironmentalEvents')]
    eventhtml=''
    for date,mon,day,title,frtitle,time,frtime,loc,frloc,cost,frcost,url in events:
        eventhtml+=f'<article class="event-card" data-event-date="{date}"><div class="event-date"><span>{t(mon,{"NOV":"NOV","DEC":"DÉC"}[mon])}</span><strong>{day}</strong></div><div><h2>{t(title,frtitle)}</h2><p><time datetime="{date}">{t(time,frtime)}</time></p><p>{t(loc,frloc)}</p><p class="fine">{t(cost,frcost)}</p><a class="text-link" href="{url}">{t("Details from King Township","Détails du canton de King")}</a></div></article>'
    return eventhtml

def register_community(make,photo):
    make('community','Stay connected to Nobleton.','Restez connecté à Nobleton.','Local news, community plans and useful ways to stay involved.','Actualités, projets communautaires et ressources pour participer à la vie locale.',current_news()+'<section class="wrap section">'+cards([
      ('https://www.king.ca/news','Local news & notices','Actualités et avis locaux','Read King Township announcements, service notices and community updates at the official source.','Consultez les annonces, avis de services et nouvelles du canton de King à la source officielle.'),
      ('/events/','Make time for community','Participez à la vie locale','A selection of upcoming activities, plus official event calendars.','Une sélection d’activités à venir et les calendriers officiels.'),
      ('https://www.king.ca/news','Planning & community projects','Aménagement et projets locaux','Find public meeting notices and planning updates. Check dates, documents and participation details with the Township.','Trouvez les avis de réunions et d’aménagement. Vérifiez les dates, documents et modalités de participation auprès du canton.')])+h('A local guide that grows with you.','Un guide local qui grandit avec vous.')+p('Have a community update, a local event or a useful resource to suggest? Send the official source and details to info@nobleton.ca. We review submissions before publishing.','Vous souhaitez proposer une nouvelle, un événement ou une ressource? Envoyez la source officielle et les détails à info@nobleton.ca. Nous examinons les propositions avant publication.')+actions(('/submit/','Add your business','Ajouter votre entreprise'),('/neighbourhoods/','Explore our neighbourhoods','Explorer les communautés'))+'</section>')
    eventhtml=event_cards()
    make('events','Good things happen close to home.','De belles activités tout près de chez vous.','Upcoming community activities in and around Nobleton.','Activités communautaires à venir à Nobleton et dans les environs.','<section class="wrap section"><div class="events-list">'+eventhtml+'</div><p id="no-upcoming-events" hidden>'+t('Visit the official calendars for the latest upcoming events.','Consultez les calendriers officiels pour les prochains événements.')+'</p><aside class="note">'+p('Details checked November 9, 2026 against King Township’s event information. Times are local to Ontario. Dates, costs and availability can change; confirm with the organizer before attending.','Détails vérifiés le 9 novembre 2026 auprès du canton de King. Les heures sont locales à l’Ontario. Dates, tarifs et disponibilité peuvent changer; confirmez auprès de l’organisateur.')+actions(('https://www.king.ca/events','Township event calendar','Calendrier du canton'),('https://www.kinglibrary.ca/','Library programs','Programmes de la bibliothèque'))+'</aside></section>')
    make('neighbourhoods','Get to know your corner of King.','Découvrez votre coin de King.','A starting point for comparing Nobleton and neighbouring communities on your own terms.','Un point de départ pour comparer Nobleton et les communautés voisines selon vos besoins.','<section class="wrap section split-feature"><div>'+photo('nobleton-lakes','Pond and autumn foliage at Nobleton Lakes in 2006','')+'</div><div>'+h('Nobleton','Nobleton')+p('Begin with the village’s local schools, library, parks and everyday services. Our Nobleton guides connect you with official resources and practical address-specific checks.','Commencez par les écoles, la bibliothèque, les parcs et les services du village. Nos guides vous orientent vers les ressources officielles et les vérifications propres à chaque adresse.')+actions(('/guide/','Explore Nobleton’s local guide','Explorer le guide de Nobleton'))+'</div></section><section class="wrap section">'+cards([
      ('https://www.king.ca/township-services','King City','King City','Compare the services and locations you use regularly. Check your actual commute and school eligibility for each address.','Comparez les services et lieux que vous fréquentez. Vérifiez les trajets et l’admissibilité scolaire pour chaque adresse.'),
      ('https://www.king.ca/township-services','Schomberg','Schomberg','Explore another King Township community and review municipal resources before deciding where to settle.','Explorez une autre communauté de King et consultez les ressources municipales avant de choisir où vous installer.'),
      ('https://www.king.ca/township-services','Pottageville','Pottageville','For each property, confirm utilities, service connections, permitted uses and the day-to-day journeys that matter to you.','Pour chaque propriété, confirmez les services publics, les raccordements, les usages permis et vos trajets quotidiens.')])+'<aside class="note">'+p('Neighbourhood names do not establish school boundaries, available listings or property-specific services. Verify details for the exact address with the appropriate authority.','Le nom d’un quartier ne détermine ni les limites scolaires, ni les annonces disponibles, ni les services d’une propriété. Vérifiez l’adresse exacte auprès de l’autorité compétente.')+'</aside>'+actions(('/ask-realtor/','Discuss neighbourhoods with Ekaterina','Parler des quartiers avec Ekaterina'))+'</section>')


def register_calculator(make):
    def num(ident,en,fr,value,minimum,maximum,step='1'):
        return f'<div><label for="{ident}">{t(en,fr)}</label><input id="{ident}" name="{ident}" type="number" inputmode="decimal" min="{minimum}" max="{maximum}" step="{step}" value="{value}" required></div>'
    form='<form id="mortgage-calculator" class="calculator-inputs">'+num('price','Home purchase price ($)','Prix d’achat ($)',1000000,1,50000000)+num('down','Down payment','Mise de fonds',20,0,50000000,'0.01')+'<div><label for="down-mode">'+t('Down payment entered as','Format de la mise de fonds')+'</label><select id="down-mode" name="downMode"><option value="percent">'+t('Percentage (%)','Pourcentage (%)')+'</option><option value="amount">'+t('Dollar amount ($)','Montant ($)')+'</option></select></div>'+num('rate','Annual interest rate (%)','Taux d’intérêt annuel (%)',4.5,0,30,'0.01')+'<div><label for="years">'+t('Amortization','Amortissement')+'</label><select id="years" name="years">'+''.join(f'<option value="{v}"'+(' selected' if v==25 else '')+'>'+t(f'{v} years',f'{v} ans')+'</option>' for v in (5,10,15,20,25,30))+'</select></div><div><label for="frequency">'+t('Payment frequency','Fréquence des versements')+'</label><select id="frequency" name="frequency">'+''.join(f'<option value="{v}">{t(en,fr)}</option>' for v,en,fr in [(12,'Monthly','Mensuelle'),(26,'Biweekly (26/year)','Aux deux semaines (26/an)'),(52,'Weekly (52/year)','Hebdomadaire (52/an)')])+'</select></div><label class="check calculator-wide"><input type="checkbox" id="insured-30" name="eligible30"><span>'+t('For an insured 30-year estimate: I am a first-time buyer or purchasing an eligible newly built home.','Pour une estimation assurée sur 30 ans : je suis premier acheteur ou j’achète une construction neuve admissible.')+'</span></label><p class="fine calculator-wide">'+t('The 4.5% starting rate is an illustration, not a current rate quote. Enter the rate you want to compare.','Le taux initial de 4,5 % est illustratif; ce n’est pas une offre de taux actuelle. Saisissez le taux à comparer.')+'</p><button class="button calculator-wide" type="submit">'+t('Calculate my payment','Calculer mon versement')+'</button><p id="calculator-error" class="calculator-wide" role="alert"></p></form>'
    labels=[('base','Mortgage before insurance','Prêt avant assurance'),('premium','Estimated insurance premium','Prime d’assurance estimée'),('loan','Mortgage including insurance','Prêt incluant l’assurance'),('paymentBase','Payment before financed insurance','Versement avant assurance financée'),('tax','Ontario tax on insurance (cash at closing)','Taxe ontarienne sur l’assurance (à payer à la clôture)'),('minimum','Minimum down payment for this price','Mise de fonds minimale pour ce prix')]
    result='<div class="calculator-results" id="calculator-results" aria-live="polite" tabindex="-1"><p class="eyebrow">'+t('YOUR ESTIMATE','VOTRE ESTIMATION')+'</p><h2 id="payment-heading">'+t('Estimated monthly payment','Versement mensuel estimé')+'</h2><p class="payment-value" id="payment-value">—</p><p class="fine">'+t('Includes financed mortgage insurance where applicable.','Inclut l’assurance hypothécaire financée, s’il y a lieu.')+'</p><dl>'+''.join(f'<div><dt>{t(en,fr)}</dt><dd data-result="{key}">—</dd></div>' for key,en,fr in labels)+'</dl>'+button('/mortgage-consultation/','Discuss this estimate','Discuter de cette estimation','light')+'</div>'
    notes=h('How this estimate works','Comment cette estimation fonctionne')+p('For an owner-occupied home with one or two units and a traditional down payment. Fixed interest is compounded semi-annually, with regular monthly, biweekly or weekly payments. Biweekly and weekly options are not accelerated payments.','Pour une résidence occupée par le propriétaire comprenant une ou deux unités, avec une mise de fonds traditionnelle. Le taux fixe est composé semestriellement; les versements réguliers sont mensuels, aux deux semaines ou hebdomadaires. Ces deux dernières options ne sont pas des versements accélérés.')+p('For eligible insured purchases below $1.5 million, this calculator applies CMHC premiums of 4.00%, 3.10% or 2.80%, depending on the loan-to-value ratio. An eligible insured 30-year amortization adds 0.20 percentage points to the premium. At 20% down or more, no borrower-paid default insurance is estimated.','Pour les achats admissibles assurés de moins de 1,5 million de dollars, cette calculatrice applique des primes SCHL de 4,00 %, 3,10 % ou 2,80 %, selon le rapport prêt-valeur. Un amortissement assuré admissible sur 30 ans ajoute 0,20 point à la prime. À 20 % de mise de fonds ou plus, aucune prime à la charge de l’emprunteur n’est estimée.')+p('Ontario’s 8% tax on the insurance premium is shown separately and is not financed. Property taxes, home insurance, legal fees, land transfer taxes, adjustments and other closing costs are excluded. Insurance and lender qualification still apply; this is an estimate, not an offer or approval.','La taxe ontarienne de 8 % sur la prime est présentée séparément et n’est pas financée. Les taxes foncières, l’assurance habitation, les frais juridiques, droits de mutation, ajustements et autres frais de clôture sont exclus. Les critères de l’assureur et du prêteur demeurent applicables : il s’agit d’une estimation, non d’une offre ou approbation.')+'<p class="fine">'+t('Method and rules reviewed November 9, 2026. Your numbers stay in your browser.','Méthode et règles révisées le 9 novembre 2026. Vos chiffres restent dans votre navigateur.')+'</p><div class="stack-links"><a href="https://www.cmhc-schl.gc.ca/professionals/project-funding-and-mortgage-financing/mortgage-loan-insurance/mortgage-loan-insurance-homeownership-programs/premium-information-for-homeowner-and-small-rental-loans">'+t('CMHC insurance premiums','Primes d’assurance SCHL')+'</a><a href="https://www.cmhc-schl.gc.ca/professionals/project-funding-and-mortgage-financing/mortgage-loan-insurance/mortgage-loan-insurance-homeownership-programs/home-start">'+t('CMHC 30-year eligibility','Admissibilité SCHL sur 30 ans')+'</a><a href="https://www.ontario.ca/document/retail-sales-tax/insurance-and-benefits-plans">'+t('Ontario tax on insurance','Taxe ontarienne sur l’assurance')+'</a></div>'
    make('mortgage-calculator','Estimate your mortgage payment.','Estimez votre versement hypothécaire.','See how your purchase price, down payment, rate and amortization work together.','Voyez comment le prix, la mise de fonds, le taux et l’amortissement influencent vos versements.','<section class="wrap section calculator-layout">'+form+result+'</section><article class="wrap reading section">'+notes+actions(('/homes-for-sale/','Explore homes','Explorer les propriétés'))+'</article><script src="/assets/mortgage-calculator.js?v=20261109" defer></script>')
